var nthUglyNumber = function(n, a, b, c) {
    const gcd = (x, y) => (y === 0n ? x : gcd(y, x % y));
    const lcm = (x, y) => (x / gcd(x, y)) * y;

    const la = BigInt(a), lb = BigInt(b), lc = BigInt(c);
    const lab = lcm(la, lb);
    const lbc = lcm(lb, lc);
    const lac = lcm(la, lc);
    const labc = lcm(lab, lc);

    const count = (x) => {
        return x / la + x / lb + x / lc - x / lab - x / lbc - x / lac + x / labc;
    };

    let low = 1n, high = 2000000000n, ans = high;
    const target = BigInt(n);
    while (low <= high) {
        const mid = (low + high) / 2n;
        if (count(mid) >= target) {
            ans = mid;
            high = mid - 1n;
        } else {
            low = mid + 1n;
        }
    }
    return Number(ans);
};
